<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { useI18n } from 'vue-i18n'
import { api } from '@/api/client'
import { useAdminAuthStore } from '@/stores/auth'
import { MessageSquare, Send, Bell, ImagePlus, RefreshCw } from 'lucide-vue-next'
import WxPusherScanBinding from '@/components/admin/WxPusherScanBinding.vue'
import WxPusherSimpleBinding from '@/components/admin/WxPusherSimpleBinding.vue'

const { t } = useI18n({ useScope:'local',messages:{
  'zh-CN':{standardMode:'标准模式（App Token）',simpleMode:'SPT 极简模式',title:'客服工作台',subtitle:'订单上下文 · 团队协作 · 离线提醒',all:'全部会话',open:'待接待',active:'处理中',waiting:'等待处理',resolved:'已解决',empty:'选择一个会话开始接待',claim:'认领会话',transfer:'转派',status:'会话状态',note:'内部备注（客户不可见）',reply:'公开回复',send:'发送',message:'输入回复，勿发送卡密或密码…',order:'已验证订单',noOrder:'未关联订单',privacy:'此处仅展示脱敏订单摘要。发货和退款请使用原业务页面。',quick:'快捷回复',quick1:'您好，请描述遇到的问题，并提供已验证的订单号。',quick2:'我们正在核查交付情况，请稍候。',quick3:'请提供遮挡敏感信息后的错误截图，我们将继续排查。',notifications:'WxPusher 提醒',config:'通知配置（主管；SPT 可不填 App Token）',enabled:'启用提醒',token:'App Token（留空保持不变）',base:'公网后台 HTTPS 地址，例如 https://shop.example/admin',save:'保存配置',uid:'你的 UID',bind:'发送绑定验证码',code:'收到的验证码',confirm:'确认绑定',test:'测试提醒',unbind:'解绑',bound:'已绑定',unbound:'尚未绑定',notice:'提醒不含聊天正文；微信渠道有激活和条数限制，建议安装 WxPusher 客户端。',error:'操作失败，请重试',image:'图片',attachmentError:'仅支持 JPEG / PNG / WebP，最大 5 MB',unread:'未读',tenant:'站点',main:'主站',agent:'处理人',unassigned:'未分配',refresh:'刷新'},
  'zh-TW':{standardMode:'標準模式（App Token）',simpleMode:'SPT 極簡模式',title:'客服工作台',subtitle:'訂單上下文 · 團隊協作 · 離線提醒',all:'全部會話',open:'待接待',active:'處理中',waiting:'等待處理',resolved:'已解決',empty:'選擇一個會話開始接待',claim:'認領會話',transfer:'轉派',status:'會話狀態',note:'內部備註（客戶不可見）',reply:'公開回覆',send:'發送',message:'輸入回覆，勿發送卡密或密碼…',order:'已驗證訂單',noOrder:'未關聯訂單',privacy:'此處僅展示脫敏訂單摘要。發貨和退款請使用原業務頁面。',quick:'快捷回覆',quick1:'您好，請描述遇到的問題，並提供已驗證的訂單號。',quick2:'我們正在核查交付情況，請稍候。',quick3:'請提供遮擋敏感資訊後的錯誤截圖，我們將繼續排查。',notifications:'WxPusher 提醒',config:'通知配置（主管；SPT 可不填 App Token）',enabled:'啟用提醒',token:'App Token（留空保持不變）',base:'公開後台 HTTPS 地址，例如 https://shop.example/admin',save:'儲存配置',uid:'你的 UID',bind:'發送綁定驗證碼',code:'收到的驗證碼',confirm:'確認綁定',test:'測試提醒',unbind:'解除綁定',bound:'已綁定',unbound:'尚未綁定',notice:'提醒不含聊天正文；微信渠道有啟用和條數限制，建議安裝 WxPusher 客戶端。',error:'操作失敗，請重試',image:'圖片',attachmentError:'僅支援 JPEG / PNG / WebP，最大 5 MB',unread:'未讀',tenant:'站點',main:'主站',agent:'處理人',unassigned:'未分配',refresh:'重新整理'},
  'en-US':{standardMode:'Standard (App Token)',simpleMode:'SPT simple mode',title:'Support desk',subtitle:'Order context · Team collaboration · Offline alerts',all:'All conversations',open:'Awaiting an agent',active:'In progress',waiting:'Waiting',resolved:'Resolved',empty:'Select a conversation to get started',claim:'Claim conversation',transfer:'Transfer',status:'Status',note:'Internal note (not visible to customers)',reply:'Public reply',send:'Send',message:'Write a reply. Never send card secrets or passwords…',order:'Verified order',noOrder:'No linked order',privacy:'Only a limited order summary is displayed. Use the existing order pages for fulfillment and refunds.',quick:'Quick replies',quick1:'Please describe the issue and provide a verified order number.',quick2:'We are checking the delivery status. Please hold on.',quick3:'Please share a screenshot with sensitive information redacted so we can investigate.',notifications:'WxPusher alerts',config:'Notification settings (SPT does not require App Token)',enabled:'Enable alerts',token:'App Token (leave blank to keep current)',base:'Public admin HTTPS URL, e.g. https://shop.example/admin',save:'Save settings',uid:'Your UID',bind:'Send verification code',code:'Code received',confirm:'Confirm binding',test:'Test alert',unbind:'Unbind',bound:'Bound',unbound:'Not bound',notice:'Alerts exclude message content. WeChat delivery has activation and volume limits. The WxPusher app is recommended.',error:'Request failed. Please retry.',image:'Image',attachmentError:'JPEG / PNG / WebP only, up to 5 MB',unread:'Unread',tenant:'Store',main:'Main store',agent:'Assignee',unassigned:'Unassigned',refresh:'Refresh'}
} })
type Conversation = {id:number;subject:string;category:string;status:string;tenant_id:number;assignee_id:number;unread_count:number;order_summary?:{order_no:string;status:string;currency:string;total_amount:string;items:{name:string;quantity:number}[]}}
type Message = {id:number;content:string;sender_type:string;internal:boolean;created_at:string;attachments:{id:number}[]}
const auth=useAdminAuthStore(),route=useRoute()
const list=ref<Conversation[]>([]),selected=ref<Conversation|null>(null),messages=ref<Message[]>([]),agents=ref<{id:number;username:string}[]>([])
const filter=ref(''),draft=ref(''),internal=ref(false),busy=ref(false),error=ref(''),polling=ref(false),notificationOpen=ref(false),target=ref(0)
const bindingMode=ref('standard')
const settings=ref({enabled:false,app_token:'',base_url:''}),binding=ref({uid:'',enabled:false,pending:false}),uid=ref(''),code=ref('')
const pending=ref<number[]>([]),imageURLs=ref<Record<number,string>>({}),scroller=ref<HTMLElement>()
let timer:ReturnType<typeof setInterval>|undefined,generation=0,clientID=''
const canConfigure=computed(()=>auth.hasPermission('GET:/admin/support/notification/settings'))
function clearImages(){Object.values(imageURLs.value).forEach(URL.revokeObjectURL);imageURLs.value={}}
function fail(e:unknown){error.value=e instanceof Error?e.message:t('error')}
async function refresh(){if(polling.value||document.hidden)return;polling.value=true;const g=generation;try{
  const res=await api.get('/admin/support/conversations',{params:{status:filter.value,page_size:100}});list.value=res.data.data||[]
  if(selected.value){const id=selected.value.id;const detail=await api.get(`/admin/support/conversations/${id}`);if(g!==generation||selected.value?.id!==id)return;selected.value=detail.data.data
    const res=await api.get(`/admin/support/conversations/${id}/messages`,{params:{after_id:messages.value[messages.value.length-1]?.id||0,limit:100}});if(g!==generation||selected.value?.id!==id)return
    const items:Message[]=res.data.data||[],seen=new Set(messages.value.map(m=>m.id));messages.value.push(...items.filter(m=>!seen.has(m.id)))
    for(const m of items)for(const a of m.attachments||[]){if(imageURLs.value[a.id])continue;try{const blob=await api.get(`/admin/support/conversations/${id}/attachments/${a.id}`,{blob:true});if(g===generation)imageURLs.value[a.id]=URL.createObjectURL(blob.data)}catch{}}
    if(items.length && messages.value.length)await api.post(`/admin/support/conversations/${id}/read`,{message_id:messages.value[messages.value.length-1]!.id})
    if(items.length){await nextTick();scroller.value?.scrollTo({top:scroller.value.scrollHeight})}
  }
}catch(e){fail(e)}finally{polling.value=false}}
async function choose(c:Conversation){generation++;clearImages();selected.value=c;messages.value=[];pending.value=[];internal.value=false;target.value=c.assignee_id;error.value='';if(!polling.value)await refresh()}
async function mutate(action:string,body?:unknown,method='post'){if(!selected.value||busy.value)return;busy.value=true;error.value='';try{const path=`/admin/support/conversations/${selected.value.id}/${action}`;if(method==='put')await api.put(path,body);else await api.post(path,body);await refresh()}catch(e){fail(e)}finally{busy.value=false}}
async function send(){if(!selected.value||busy.value||(!draft.value.trim()&&!pending.value.length))return;clientID ||= crypto.randomUUID();busy.value=true;error.value='';try{await api.post(`/admin/support/conversations/${selected.value.id}/messages`,{content:draft.value,client_id:clientID,internal:internal.value,attachment_ids:pending.value});draft.value='';pending.value=[];clientID='';await refresh()}catch(e){fail(e)}finally{busy.value=false}}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file||!selected.value||busy.value)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){error.value=t('attachmentError');return}busy.value=true;try{const body=new FormData();body.append('file',file);const res=await api.post(`/admin/support/conversations/${selected.value.id}/attachments`,body);pending.value.push(res.data.data.id)}catch(e){fail(e)}finally{busy.value=false}}
function onSimpleBound(){binding.value={uid:'',enabled:true,pending:false};uid.value='';code.value=''}
function onScanBound(value:string){uid.value=value;binding.value={uid:value,enabled:true,pending:false};code.value=''}
async function notifications(){notificationOpen.value=!notificationOpen.value;if(!notificationOpen.value)return;try{const res=await api.get('/admin/support/notification/binding');binding.value=res.data.data;uid.value=binding.value.uid;bindingMode.value=res.data.data.mode==='simple'?'simple':'standard';if(canConfigure.value){const cfg=await api.get('/admin/support/notification/settings');settings.value={...cfg.data.data,app_token:''}}}catch(e){fail(e)}}
async function notifyAction(action:string){if(busy.value)return;busy.value=true;error.value='';try{switch(action){case 'save':await api.put('/admin/support/notification/settings',settings.value);break;case 'begin':await api.post('/admin/support/notification/binding',{uid:uid.value});binding.value.pending=true;break;case 'confirm':await api.post('/admin/support/notification/binding/confirm',{code:code.value});binding.value={uid:uid.value,enabled:true,pending:false};code.value='';break;case 'test':await api.post('/admin/support/notification/test');break;case 'unbind':await api.delete('/admin/support/notification/binding');binding.value={uid:'',enabled:false,pending:false};break}}catch(e){fail(e)}finally{busy.value=false}}
onMounted(async()=>{try{const res=await api.get('/admin/support/agents');agents.value=res.data.data||[];await refresh();const id=Number(route.query.conversation);const c=list.value.find(c=>c.id===id);if(c)await choose(c)}catch(e){fail(e)}timer=setInterval(()=>void refresh(),5000)})
onUnmounted(()=>{generation++;clearInterval(timer);clearImages()})
</script>

<template>
  <div class="space-y-5">
    <header class="flex items-center justify-between gap-3"><div><h1 class="text-2xl font-semibold tracking-tight">{{t('title')}}</h1><p class="mt-1 text-sm text-muted-foreground">{{t('subtitle')}}</p></div><div class="flex gap-2"><button class="rounded-lg border p-2" :aria-label="t('refresh')" @click="refresh"><RefreshCw :size="18"/></button><button class="flex items-center gap-2 rounded-lg border px-3 py-2 text-sm" @click="notifications"><Bell :size="16"/>{{t('notifications')}}</button></div></header>
    <p v-if="error" class="rounded-xl bg-destructive/10 p-3 text-sm text-destructive" role="alert">{{error}}</p>
    <section v-if="notificationOpen" class="grid gap-5 rounded-xl border bg-card p-5 md:grid-cols-2"><div><h2 class="mb-3 font-semibold">{{t('notifications')}}</h2><p class="mb-3 text-xs text-muted-foreground">{{t('notice')}}</p><p class="mb-3 text-sm">{{binding.enabled?t('bound')+': '+(binding.uid||'SPT'):t('unbound')}}</p><div class="mb-3 flex gap-2"><button class="rounded-lg border px-3 py-2 text-xs" :class="bindingMode==='standard'?'bg-primary text-primary-foreground':''" @click="bindingMode='standard'">{{t('standardMode')}}</button><button class="rounded-lg border px-3 py-2 text-xs" :class="bindingMode==='simple'?'bg-primary text-primary-foreground':''" @click="bindingMode='simple'">{{t('simpleMode')}}</button></div><WxPusherSimpleBinding v-if="bindingMode==='simple'" @bound="onSimpleBound"/><WxPusherScanBinding v-if="bindingMode==='standard'" :active="notificationOpen" @bound="onScanBound"/><input v-if="bindingMode==='standard'" v-model="uid" class="mb-2 w-full rounded-lg border bg-background p-2" :placeholder="t('uid')"/><button class="rounded-lg border px-3 py-2 text-sm" :disabled="busy" v-if="bindingMode==='standard'" @click="notifyAction('begin')">{{t('bind')}}</button><div v-if="binding.pending && bindingMode==='standard'" class="mt-3 flex gap-2"><input v-model="code" class="min-w-0 rounded-lg border bg-background p-2" :placeholder="t('code')"/><button :disabled="busy" @click="notifyAction('confirm')">{{t('confirm')}}</button></div><div v-if="binding.enabled" class="mt-3 flex gap-3 text-sm"><button :disabled="busy" @click="notifyAction('test')">{{t('test')}}</button><button class="text-destructive" :disabled="busy" @click="notifyAction('unbind')">{{t('unbind')}}</button></div></div><div v-if="canConfigure"><h2 class="mb-3 font-semibold">{{t('config')}}</h2><label class="mb-3 flex items-center gap-2 text-sm"><input v-model="settings.enabled" type="checkbox"/>{{t('enabled')}}</label><input v-model="settings.app_token" type="password" autocomplete="new-password" class="mb-2 w-full rounded-lg border bg-background p-2" :placeholder="t('token')"/><input v-model="settings.base_url" class="mb-2 w-full rounded-lg border bg-background p-2" :placeholder="t('base')"/><button :disabled="busy" class="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground" @click="notifyAction('save')">{{t('save')}}</button></div></section>
    <div class="grid min-h-[600px] overflow-hidden rounded-xl border bg-card lg:h-[calc(100vh-210px)] lg:grid-cols-[260px_minmax(0,1fr)_260px]">
      <aside class="border-b lg:border-b-0 lg:border-r"><div class="border-b p-3"><select v-model="filter" class="w-full rounded-lg border bg-background p-2 text-sm" @change="refresh"><option value="">{{t('all')}}</option><option v-for="status in ['open','active','waiting','resolved']" :key="status" :value="status">{{t(status)}}</option></select></div><div class="max-h-56 overflow-auto p-2 lg:max-h-[calc(100vh-280px)]"><button v-for="c in list" :key="c.id" class="mb-1 w-full rounded-lg p-3 text-left transition" :class="selected?.id===c.id?'bg-primary/10':'hover:bg-muted'" @click="choose(c)"><div class="flex justify-between gap-2"><span class="truncate text-sm font-medium">{{c.subject}}</span><span v-if="c.unread_count" class="rounded-full bg-primary px-2 text-xs text-primary-foreground">{{c.unread_count}}</span></div><p class="mt-1 text-xs text-muted-foreground">CS-{{c.id}} · {{t(c.status)}} · {{c.tenant_id?'#'+c.tenant_id:t('main')}}</p></button></div></aside>
      <section v-if="selected" class="flex min-h-[500px] min-w-0 flex-col lg:min-h-0"><header class="flex items-center justify-between border-b px-4 py-3"><div><h2 class="font-semibold">{{selected.subject}}</h2><p class="text-xs text-muted-foreground">CS-{{selected.id}}</p></div><button v-if="!selected.assignee_id" class="rounded-lg bg-primary px-3 py-2 text-sm text-primary-foreground" :disabled="busy" @click="mutate('claim')">{{t('claim')}}</button></header><div ref="scroller" class="flex-1 space-y-4 overflow-auto p-4"><div v-for="m in messages" :key="m.id" class="flex" :class="m.sender_type==='admin'?'justify-end':'justify-start'"><div class="max-w-[85%] rounded-xl px-4 py-3" :class="m.internal?'border border-amber-400/40 bg-amber-400/10':m.sender_type==='admin'?'bg-primary text-primary-foreground':'bg-muted'"><span v-if="m.internal" class="mb-1 block text-xs font-medium">{{t('note')}}</span><p class="whitespace-pre-wrap break-words text-sm">{{m.content}}</p><img v-for="a in m.attachments||[]" :key="a.id" :src="imageURLs[a.id]" :alt="t('image')" class="mt-2 max-h-60 rounded-lg"/><time class="mt-2 block text-[10px] opacity-60">{{new Date(m.created_at).toLocaleString()}}</time></div></div></div><form class="space-y-2 border-t p-4" @submit.prevent="send"><label class="flex items-center gap-2 text-xs" :class="internal?'text-amber-600':'text-muted-foreground'"><input v-model="internal" type="checkbox"/>{{internal?t('note'):t('reply')}}</label><textarea v-model="draft" rows="3" maxlength="4000" class="w-full resize-none rounded-xl border bg-background p-3 text-sm" :placeholder="t('message')" :disabled="busy"/><div class="flex items-center justify-between"><label class="cursor-pointer text-muted-foreground"><ImagePlus :size="20"/><input type="file" accept="image/jpeg,image/png,image/webp" class="hidden" :disabled="busy||pending.length>=4" @change="upload"/></label><span v-if="pending.length" class="text-xs">{{t('image')}}: {{pending.length}} / 4</span><button :disabled="busy||(!draft.trim()&&!pending.length)" class="flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-40"><Send :size="15"/>{{t('send')}}</button></div></form></section>
      <section v-else class="flex min-h-64 items-center justify-center gap-3 text-muted-foreground"><MessageSquare :size="24"/>{{t('empty')}}</section>
      <aside v-if="selected" class="space-y-5 border-t p-4 lg:border-l lg:border-t-0"><div><label class="text-xs text-muted-foreground">{{t('status')}}</label><select :value="selected.status" class="mt-2 w-full rounded-lg border bg-background p-2 text-sm" :disabled="busy" @change="mutate('status',{status:($event.target as HTMLSelectElement).value},'put')"><option v-for="s in ['open','active','waiting','resolved']" :key="s" :value="s">{{t(s)}}</option></select></div><div><label class="text-xs text-muted-foreground">{{t('agent')}}</label><select v-model="target" class="mt-2 w-full rounded-lg border bg-background p-2 text-sm"><option :value="0">{{t('unassigned')}}</option><option v-for="a in agents" :key="a.id" :value="a.id">{{a.username}}</option></select><button :disabled="busy||!target" class="mt-2 text-sm text-primary" @click="mutate('assignee',{admin_id:target},'put')">{{t('transfer')}}</button></div><div class="rounded-lg bg-muted/40 p-3"><h3 class="mb-2 text-sm font-medium">{{selected.order_summary?t('order'):t('noOrder')}}</h3><template v-if="selected.order_summary"><p class="break-all text-xs">{{selected.order_summary.order_no}}</p><p class="mt-2 text-sm">{{selected.order_summary.currency}} {{selected.order_summary.total_amount}}</p><p v-for="(item,i) in selected.order_summary.items" :key="i" class="mt-2 text-xs">{{item.name}} × {{item.quantity}}</p></template><p class="mt-3 text-xs leading-5 text-muted-foreground">{{t('privacy')}}</p></div><div><h3 class="mb-2 text-sm font-medium">{{t('quick')}}</h3><button v-for="key in ['quick1','quick2','quick3']" :key="key" class="mb-2 w-full rounded-lg border p-2 text-left text-xs hover:bg-muted" @click="draft=t(key)">{{t(key)}}</button></div></aside>
    </div>
  </div>
</template>